using FrameShift.Core.AI.RemoveNoise;
using Microsoft.ML.OnnxRuntime;
using NAudio.Wave;
using Xunit;

namespace FrameShift.Tests;

public sealed class RemoveNoiseCancellationTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), $"frameshift débruitage annulation {Guid.NewGuid():N}");

    // Generated by tools/scripts/generate_remove_noise_test_models.py.
    // The sub-kilobyte fixtures have the encoder/decoder tensor contracts, not
    // denoising weights. A busy stage loops up to 20 million times for >20 frames;
    // short audio completes normally on the very same session after cancellation.
    [Theory]
    [InlineData("encoder")]
    [InlineData("erb")]
    [InlineData("df")]
    public async Task CancellationDuringEachNativeStageStopsWithoutOutputAndAllowsReuse(string busyStage)
    {
        using var engine = CreateEngine(busyStage);
        var source = WriteWave("long été.wav", 48000);
        var shortSource = WriteWave("short été.wav", 480);
        var desired = Path.Combine(_root, "long été_clean.wav");
        File.WriteAllText(desired, "foreign output");
        using var cancellation = new CancellationTokenSource();
        var inferenceStarted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var run = engine.RemoveNoiseAsync(source, new InlineProgress(p =>
        {
            if (p.percent == 45) inferenceStarted.TrySetResult();
        }), cancellation.Token);
        try
        {
            await inferenceStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            await Task.Delay(200); // fast stages finish; the selected native Loop remains active
            Assert.False(run.IsCompleted, $"The {busyStage} fixture did not hold inference open.");
            cancellation.Cancel();

            var exception = await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
                run.WaitAsync(TimeSpan.FromSeconds(3)));
            Assert.Equal(cancellation.Token, exception.CancellationToken);
            Assert.Equal("foreign output", File.ReadAllText(desired));
            Assert.False(File.Exists(Path.Combine(_root, "long été_clean_001.wav")));
            Assert.Empty(Directory.GetDirectories(_root, ".frameshift-*"));

            var saved = await engine.RemoveNoiseAsync(shortSource, new InlineProgress(_ => { }), CancellationToken.None)
                .WaitAsync(TimeSpan.FromSeconds(5));
            using var decoded = new WaveFileReader(saved);
            Assert.Equal(48000, decoded.WaveFormat.SampleRate);
            Assert.Equal(1, decoded.WaveFormat.Channels);
            Assert.Equal(480 * sizeof(short), decoded.Length);
        }
        finally
        {
            cancellation.Cancel();
            // Always join native work before disposing its sessions, including a failed
            // interruption test. The fixture is finite if cancellation is broken.
            try { await run; } catch (OperationCanceledException) { }
        }
    }

    [Fact]
    public async Task PreCanceledRequestDoesNotEnterInferenceOrCreateOutput()
    {
        using var engine = CreateEngine("encoder");
        var source = WriteWave("pre-canceled.wav", 48000);
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => engine.RemoveNoiseAsync(source,
            new InlineProgress(_ => Assert.Fail("Pre-canceled work reported progress.")), cancellation.Token));

        Assert.Equal(new[] { source }, Directory.GetFiles(_root));
    }

    [Fact]
    public void RealOnnxErrorsArePreservedAndDoNotPoisonTheSession()
    {
        using var session = CreateSession("encoder", false);
        Assert.Throws<OnnxRuntimeException>(() =>
        {
            using var results = RemoveNoiseEngine.RunInference(session, Array.Empty<NamedOnnxValue>(), CancellationToken.None);
        });

        var inputs = new[]
        {
            NamedOnnxValue.CreateFromTensor("feat_erb", new Microsoft.ML.OnnxRuntime.Tensors.DenseTensor<float>(new[] { 1, 1, 3, 32 })),
            NamedOnnxValue.CreateFromTensor("feat_spec", new Microsoft.ML.OnnxRuntime.Tensors.DenseTensor<float>(new[] { 1, 2, 3, 96 }))
        };
        using var valid = RemoveNoiseEngine.RunInference(session, inputs, CancellationToken.None);
        Assert.Equal("emb", Assert.Single(valid).Name);
    }

    private static RemoveNoiseEngine CreateEngine(string busyStage)
    {
        var encoder = CreateSession("encoder", busyStage == "encoder");
        InferenceSession? erb = null;
        try
        {
            erb = CreateSession("erb", busyStage == "erb");
            return new RemoveNoiseEngine(encoder, erb, CreateSession("df", busyStage == "df"));
        }
        catch
        {
            encoder.Dispose();
            erb?.Dispose();
            throw;
        }
    }

    private static InferenceSession CreateSession(string stage, bool busy)
    {
        using var options = new SessionOptions
        {
            IntraOpNumThreads = 1,
            InterOpNumThreads = 1,
            GraphOptimizationLevel = GraphOptimizationLevel.ORT_ENABLE_ALL
        };
        return new InferenceSession(Path.Combine(AppContext.BaseDirectory, "Assets", "RemoveNoise",
            stage + (busy ? "-busy" : "") + ".onnx"), options);
    }

    private string WriteWave(string name, int samples)
    {
        Directory.CreateDirectory(_root);
        var path = Path.Combine(_root, name);
        using var writer = new WaveFileWriter(path, new WaveFormat(48000, 16, 1));
        writer.Write(new byte[samples * sizeof(short)], 0, samples * sizeof(short));
        return path;
    }

    public void Dispose()
    {
        if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true);
    }

    private sealed class InlineProgress(Action<(int percent, string status)> report) : IProgress<(int percent, string status)>
    {
        public void Report((int percent, string status) value) => report(value);
    }
}
